/* Village Watchtower — client-only interface; all data generated by scheduled Actions. */
'use strict';
const q = (s) => document.querySelector(s);
const state = {snapshot: null, history: [], filter: 'all', search: ''};
const ui = (tag, cls, value) => {const el = document.createElement(tag); if(cls) el.className=cls; if(value!==undefined) el.textContent=String(value); return el;};
const put = (id, value) => {const el = document.getElementById(id); if(el) el.textContent=String(value);};
const when = (stamp) => {if (!stamp) return 'Time unavailable'; const d=new Date(stamp); return Number.isNaN(d.getTime()) ? stamp : d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});};
function external(url){
  try {const u=new URL(url); return (u.protocol==='https:' && u.hostname==='gitlab.com') ? u.href : null;}
  catch(_){return null;}
}
function outbound(label,url,cls=''){
  const a=ui('a',cls,label); const safe=external(url);
  if(safe){a.href=safe;a.target='_blank';a.rel='noopener noreferrer';}
  return a;
}
function empty(parent,title,desc){
  const wrap=ui('div','empty-state');wrap.append(ui('div','empty-icon','◎'),ui('h3','',title),ui('p','',desc));parent.append(wrap);
}
function renderCounts(){
  const snap=state.snapshot;
  const ready=snap?.status==='ready';
  put('count-groups',ready?snap.counts.groups:'—'); put('count-members',ready && snap.membership_status==='available'?snap.counts.memberships:'—');
  put('count-repos',ready?snap.counts.repos:'—');put('count-new',ready?snap.counts.new:'—');
  put('checked',ready?`Last scan: ${when(snap.checked_at)}${snap.membership_status!=='available'?' · Member tracking needs GitLab authentication':''}`:'No snapshot yet');
  put('status',ready?'Snapshot available':'Awaiting first scan');
  q('#status-dot').classList.toggle('pending',!ready);
}
function renderEvents(){
  const pane=q('#events');pane.replaceChildren();
  const entries=state.history.filter(e=>(state.filter==='all'||e.kind===state.filter) &&
    `${e.name||''} ${e.path||''} ${e.username||''}`.toLowerCase().includes(state.search));
  put('history-total',`${state.history.length} events`);
  if(!state.snapshot || state.snapshot.status!=='ready'){
    empty(pane,'Awaiting first scan','GitHub Actions will establish the first snapshot before reporting discoveries.');return;
  }
  if(!entries.length){empty(pane,state.history.length?'Nothing matches the filters':'No new discoveries yet',
    state.history.length?'Try another search or category.':'The initial scan forms a baseline. Future additions will appear here.');return;}
  for(const event of entries.slice(0,400)){
    const box=ui('article',`event-item ${event.kind}`);
    box.append(ui('div','event-icon',({group:'🌳',member:'👥',repo:'📁'})[event.kind]||'✳'));
    const body=ui('div','event-body'), top=ui('div','event-top');
    top.append(ui('span','type-tag',({group:'NEW SUBGROUP',member:'NEW MEMBER',repo:'NEW ONBOARDING REPO'})[event.kind]||'DISCOVERY'),ui('span','event-date',when(event.detected_at)));
    body.append(top,outbound(event.name,event.url,'event-title'),ui('div','event-path',event.path||''));
    box.append(body);pane.append(box);
  }
}
function renderTree(){
  const pane=q('#tree');pane.replaceChildren(); const groups=Object.values(state.snapshot?.groups||{}).sort((a,b)=>a.path.localeCompare(b.path));
  put('group-total',groups.length);
  if(!groups.length){pane.append(ui('p','loading','No public subgroups found yet.'));return;}
  const counters={};for(const m of Object.values(state.snapshot.memberships||{})){counters[m.group_id]=(counters[m.group_id]||0)+1;}
  for(const g of groups){
    const row=ui('div','tree-row'),link=outbound('',''+g.url,'tree-link');
    const depth=Math.max(0,g.path.split('/').length-2);
    link.style.paddingLeft=`${Math.min(depth,8)*12}px`;
    link.append(ui('span','tree-marker',depth?'└':'⌁'),document.createTextNode(g.name));
    link.append(ui('span','row-sub',g.path));
    row.append(link,ui('span','member-mini',state.snapshot.membership_status==='available'?`${counters[g.id]||0} direct`:'auth needed'));pane.append(row);
  }
}
function renderRepos(){
  const pane=q('#repo-list');pane.replaceChildren();const repos=Object.values(state.snapshot?.repos||{}).sort((a,b)=>(b.created_at||'').localeCompare(a.created_at||''));
  put('repo-total',repos.length);
  if(!repos.length){pane.append(ui('p','loading','No publicly visible onboarding repositories found.'));return;}
  for(const repo of repos){
    const row=ui('div','repo-row'),link=outbound('',repo.url,'repo-link');
    link.append(ui('span','repo-mark','▤'),document.createTextNode(repo.name),ui('span','row-sub',repo.path));
    row.append(link,ui('span','member-mini','↗'));pane.append(row);
  }
}
async function refresh(){
  const button=q('#refresh');button.disabled=true;button.textContent='↻ Loading…';
  try{
    const cb=`?v=${Date.now()}`;
    const [snapRes,historyRes]=await Promise.all([fetch('./data/snapshot.json'+cb,{cache:'no-store'}),fetch('./data/history.json'+cb,{cache:'no-store'})]);
    if(!snapRes.ok||!historyRes.ok)throw Error(`HTTP ${snapRes.status}/${historyRes.status}`);
    const snap=await snapRes.json(),history=await historyRes.json();
    if(!snap||!history||!Array.isArray(history.events))throw Error('Invalid data files');
    state.snapshot=snap;state.history=history.events;
    renderCounts();renderEvents();renderTree();renderRepos();
  }catch(err){
    console.error('Watchtower data unavailable:',err);
    put('status','Could not load snapshot');put('checked','Try refreshing again');
    const pane=q('#events');pane.replaceChildren();empty(pane,'Data currently unavailable','The published data files could not be loaded. The GitLab monitor may not have completed a first scan yet.');
  }finally{button.disabled=false;button.textContent='↻ Refresh data';}
}
q('#refresh').addEventListener('click',refresh);
q('#search').addEventListener('input',(e)=>{state.search=e.target.value.trim().toLowerCase();renderEvents();});
for(const button of document.querySelectorAll('[data-filter]'))button.addEventListener('click',()=>{
  state.filter=button.dataset.filter;
  for(const option of document.querySelectorAll('[data-filter]')){const active=option===button;option.classList.toggle('active',active);option.setAttribute('aria-pressed',String(active));}
  renderEvents();
});
refresh();
